#!/usr/bin/env node
/**
 * Southbank S&C — Monday 7 PM Open Gym auto-booker
 *
 * Logs in, finds next Monday's 7 PM Open Gym class, and books it.
 * Designed to run as a weekly cron job, 7 days before the class.
 *
 * Usage:
 *   node book-open-gym.mjs                  # book next available Monday Open Gym
 *   node book-open-gym.mjs --date 2026-09-07  # book a specific Monday
 *   node book-open-gym.mjs --dry-run         # just find the class, don't book
 */

const BASE_URL = 'https://app.southbank-sc.com';

// ── Config ──────────────────────────────────────────────────────────────
const EMAIL    = process.env.SOUTHBANK_EMAIL    || 'andrew.mercer@gmail.com';
const PASSWORD = process.env.SOUTHBANK_PASSWORD || 'Kettlebell42!';

const TARGET_CLASS_TYPE = 'open_gym';
const TARGET_HOUR_UTC   = 9;  // 09:00 UTC = 19:00 AEST (7 PM)

// ── Helpers ─────────────────────────────────────────────────────────────

function log(msg) {
  console.log(`[${new Date().toISOString()}] ${msg}`);
}

function getNextMonday(fromDate = new Date()) {
  const d = new Date(fromDate);
  const day = d.getDay(); // 0=Sun, 1=Mon, ...
  const daysUntilMonday = day === 0 ? 1 : day === 1 ? 7 : (8 - day);
  d.setDate(d.getDate() + daysUntilMonday);
  d.setHours(0, 0, 0, 0);
  return d;
}

function formatDate(d) {
  return d.toISOString().split('T')[0];
}

/**
 * A minimal cookie jar that captures Set-Cookie headers and replays them.
 * Works with httpOnly cookies that browser fetch() hides from JS.
 */
class CookieJar {
  constructor() { this.cookies = new Map(); }

  capture(response) {
    const raw = response.headers.raw?.() ?? {};
    const setCookies = raw['set-cookie'] || [];
    for (const sc of setCookies) {
      const [pair] = sc.split(';');
      const [name, ...rest] = pair.split('=');
      this.cookies.set(name.trim(), rest.join('=').trim());
    }
  }

  header() {
    return [...this.cookies.entries()].map(([k, v]) => `${k}=${v}`).join('; ');
  }
}

// ── API calls ───────────────────────────────────────────────────────────

async function login(jar) {
  log('Logging in...');
  const res = await fetch(`${BASE_URL}/login`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email: EMAIL, password: PASSWORD }),
    redirect: 'manual',
  });

  // Capture cookies from raw headers
  const setCookieHeaders = res.headers.getSetCookie?.() || [];
  for (const sc of setCookieHeaders) {
    const [pair] = sc.split(';');
    const [name, ...rest] = pair.split('=');
    jar.cookies.set(name.trim(), rest.join('=').trim());
  }

  if (!res.ok) {
    const body = await res.text();
    throw new Error(`Login failed (${res.status}): ${body}`);
  }

  const data = await res.json();
  log(`Logged in as ${data.user.firstName} ${data.user.lastName} (${data.user.membershipType})`);
  return data.user;
}

async function graphql(jar, query, variables = {}) {
  const res = await fetch(`${BASE_URL}/graphql`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Cookie': jar.header(),
    },
    body: JSON.stringify({ query, variables }),
  });

  // Capture any refreshed cookies
  const setCookieHeaders = res.headers.getSetCookie?.() || [];
  for (const sc of setCookieHeaders) {
    const [pair] = sc.split(';');
    const [name, ...rest] = pair.split('=');
    jar.cookies.set(name.trim(), rest.join('=').trim());
  }

  const data = await res.json();
  if (data.errors) {
    throw new Error(`GraphQL error: ${JSON.stringify(data.errors)}`);
  }
  return data.data;
}

async function findOpenGymClass(jar, targetDate) {
  const from = `${formatDate(targetDate)}T00:00:00Z`;
  const to   = `${formatDate(targetDate)}T23:59:59Z`;

  log(`Searching for classes on ${formatDate(targetDate)}...`);

  const { classes } = await graphql(jar, `
    query ($from: DateTime!, $to: DateTime!) {
      classes(from: $from, to: $to) {
        id classType startsAt endsAt capacity coachName confirmedCount spotsLeft
      }
    }
  `, { from, to });

  // Find the 7 PM (09:00 UTC) Open Gym
  const match = classes.find(c => {
    const hour = new Date(c.startsAt).getUTCHours();
    return c.classType === TARGET_CLASS_TYPE && hour === TARGET_HOUR_UTC;
  });

  if (!match) {
    log(`Available classes on ${formatDate(targetDate)}:`);
    for (const c of classes) {
      log(`  ${c.classType} @ ${c.startsAt} — ${c.spotsLeft}/${c.capacity} spots left`);
    }
    throw new Error(`No ${TARGET_CLASS_TYPE} class found at ${TARGET_HOUR_UTC}:00 UTC on ${formatDate(targetDate)}`);
  }

  log(`Found: ${match.classType} @ ${match.startsAt} (coach: ${match.coachName}) — ${match.spotsLeft}/${match.capacity} spots left`);
  return match;
}

async function bookClass(jar, classInstanceId) {
  log(`Booking class ${classInstanceId}...`);

  const { createReservation } = await graphql(jar, `
    mutation ($classInstanceId: ID!) {
      createReservation(classInstanceId: $classInstanceId) {
        reservation {
          id status waitlistPosition createdAt
          classInstance { id classType startsAt coachName }
        }
        errorCode
      }
    }
  `, { classInstanceId });

  if (createReservation.errorCode) {
    throw new Error(`Booking failed: ${createReservation.errorCode}`);
  }

  const r = createReservation.reservation;
  if (r.status === 'confirmed') {
    log(`✅ BOOKED! Reservation ${r.id} confirmed for ${r.classInstance.classType} @ ${r.classInstance.startsAt}`);
  } else if (r.status === 'waitlisted') {
    log(`⏳ Waitlisted (position ${r.waitlistPosition}) for ${r.classInstance.classType} @ ${r.classInstance.startsAt}`);
  } else {
    log(`Reservation ${r.id} — status: ${r.status}`);
  }

  return r;
}

async function checkExistingBooking(jar, targetClassId) {
  const { myReservations } = await graphql(jar, `{
    myReservations {
      id status cancelledAt
      classInstance { id }
    }
  }`);

  return myReservations.find(
    r => r.classInstance.id === targetClassId && !r.cancelledAt && r.status !== 'cancelled'
  );
}

// ── Main ────────────────────────────────────────────────────────────────

async function main() {
  const args = process.argv.slice(2);
  const dryRun = args.includes('--dry-run');
  const dateArg = args.find((_, i, a) => a[i - 1] === '--date');

  let targetDate;
  if (dateArg) {
    targetDate = new Date(dateArg + 'T00:00:00Z');
    if (isNaN(targetDate)) throw new Error(`Invalid date: ${dateArg}`);
  } else {
    targetDate = getNextMonday();
  }

  log(`Target: Monday ${formatDate(targetDate)} — 7:00 PM AEST Open Gym`);

  const jar = new CookieJar();

  // 1. Login
  await login(jar);

  // 2. Find the class
  const cls = await findOpenGymClass(jar, targetDate);

  // 3. Check if already booked
  const existing = await checkExistingBooking(jar, cls.id);
  if (existing) {
    log(`Already booked! Reservation ${existing.id} (${existing.status}). Nothing to do.`);
    return;
  }

  if (cls.spotsLeft === 0) {
    log(`⚠️  Class is full (${cls.confirmedCount}/${cls.capacity}). Will attempt anyway (waitlist).`);
  }

  // 4. Book it
  if (dryRun) {
    log('Dry run — skipping booking.');
    return;
  }

  const retries = 3;
  for (let attempt = 1; attempt <= retries; attempt++) {
    try {
      await bookClass(jar, cls.id);
      return;
    } catch (err) {
      log(`Attempt ${attempt}/${retries} failed: ${err.message}`);
      if (attempt < retries) {
        const delay = 1000 * attempt;
        log(`Retrying in ${delay}ms...`);
        await new Promise(r => setTimeout(r, delay));
      } else {
        throw err;
      }
    }
  }
}

main().catch(err => {
  log(`❌ FAILED: ${err.message}`);
  process.exit(1);
});

