#!/usr/bin/env node
/**
 * Southbank S&C — Monday 7 PM Open Gym auto-booker
 *
 * API details (discovered via introspection):
 *   Auth:     POST /login  { email, password }  → sets httpOnly session cookie
 *   GraphQL:  POST /graphql  (Apollo, cookie-authenticated)
 *
 *   Queries:  classes(from, to)  → [ClassInstance]
 *             classInstance(id)  → ClassInstance
 *             me                → User
 *             myReservations    → [Reservation]
 *
 *   Mutations: createReservation(classInstanceId!)  → { reservation, errorCode }
 *              cancelReservation(reservationId!)     → { reservationId, success }
 *
 *   ClassInstance fields: id, classType, startsAt, endsAt, capacity,
 *                         coachName, confirmedCount, spotsLeft
 *
 * Usage:
 *   node book-open-gym.mjs                       # book next Monday's Open Gym
 *   node book-open-gym.mjs --date 2026-09-07     # book a specific Monday
 *   node book-open-gym.mjs --dry-run             # find class but don't book
 */

const BASE_URL = 'https://app.southbank-sc.com';

// ── Config ──────────────────────────────────────────────────────────────
const EMAIL    = process.env.SOUTHBANK_EMAIL    || 'andrew.mercer@gmail.com';
const PASSWORD = process.env.SOUTHBANK_PASSWORD || 'Kettlebell42!';

const TARGET_CLASS_TYPE = 'open_gym';
const TARGET_HOUR_UTC   = 9;   // 09:00 UTC = 19:00 AEST (7 PM)
const TARGET_DAY        = 1;   // Monday (0=Sun … 6=Sat)

// ── Helpers ─────────────────────────────────────────────────────────────

function log(msg) {
  console.log(`[${new Date().toISOString()}] ${msg}`);
}

function nextWeekday(day, from = new Date()) {
  const d = new Date(from);
  const diff = (day - d.getUTCDay() + 7) % 7 || 7;   // always next, not today
  d.setUTCDate(d.getUTCDate() + diff);
  d.setUTCHours(0, 0, 0, 0);
  return d;
}

function fmtDate(d) {
  return d.toISOString().split('T')[0];
}

// ── Cookie jar (for httpOnly session cookies) ───────────────────────────

class CookieJar {
  constructor() { this.pairs = []; }

  /** Capture Set-Cookie headers from a Node fetch Response. */
  capture(res) {
    // Node 18+ (undici): getSetCookie() returns string[]
    const raw = typeof res.headers.getSetCookie === 'function'
      ? res.headers.getSetCookie()
      : (res.headers.get('set-cookie') || '').split(/,(?=\s*\w+=)/);

    for (const line of raw) {
      if (!line) continue;
      const [pair] = line.split(';');
      const eq = pair.indexOf('=');
      if (eq === -1) continue;
      const name = pair.slice(0, eq).trim();
      const value = pair.slice(eq + 1).trim();
      // Replace existing or append
      const idx = this.pairs.findIndex(([n]) => n === name);
      if (idx >= 0) this.pairs[idx] = [name, value];
      else this.pairs.push([name, value]);
    }
  }

  header() {
    return this.pairs.map(([n, v]) => `${n}=${v}`).join('; ');
  }
}

// ── API layer ───────────────────────────────────────────────────────────

async function login(jar) {
  log('Logging in…');
  const res = await fetch(`${BASE_URL}/login`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email: EMAIL, password: PASSWORD }),
  });
  jar.capture(res);

  if (!res.ok) {
    const body = await res.text();
    throw new Error(`Login failed (${res.status}): ${body}`);
  }

  const { user } = await res.json();
  log(`Logged in as ${user.firstName} ${user.lastName} (${user.membershipType})`);
  return user;
}

async function gql(jar, query, variables = {}) {
  const res = await fetch(`${BASE_URL}/graphql`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      ...(jar.header() ? { Cookie: jar.header() } : {}),
    },
    body: JSON.stringify({ query, variables }),
  });
  jar.capture(res);

  const json = await res.json();
  if (json.errors?.length) {
    throw new Error(`GraphQL: ${json.errors.map(e => e.message).join('; ')}`);
  }
  return json.data;
}

// ── Domain helpers ──────────────────────────────────────────────────────

async function findOpenGym(jar, date) {
  const from = `${fmtDate(date)}T00:00:00Z`;
  const to   = `${fmtDate(date)}T23:59:59Z`;
  log(`Fetching classes for ${fmtDate(date)}…`);

  const { classes } = await gql(jar, `
    query ($from: DateTime!, $to: DateTime!) {
      classes(from: $from, to: $to) {
        id classType startsAt endsAt capacity coachName confirmedCount spotsLeft
      }
    }`, { from, to });

  const match = classes.find(c =>
    c.classType === TARGET_CLASS_TYPE &&
    new Date(c.startsAt).getUTCHours() === TARGET_HOUR_UTC
  );

  if (!match) {
    log('Classes found on that day:');
    classes.forEach(c => log(`  ${c.classType} @ ${c.startsAt} — ${c.spotsLeft}/${c.capacity}`));
    throw new Error(`No ${TARGET_CLASS_TYPE} at ${TARGET_HOUR_UTC}:00 UTC on ${fmtDate(date)}`);
  }

  log(`Found: ${match.classType} @ ${match.startsAt} (coach ${match.coachName}) — ${match.spotsLeft}/${match.capacity} spots left`);
  return match;
}

async function alreadyBooked(jar, classId) {
  const { myReservations } = await gql(jar, `{
    myReservations {
      id status cancelledAt classInstance { id }
    }
  }`);
  return myReservations.find(r =>
    r.classInstance.id === classId &&
    !r.cancelledAt &&
    r.status !== 'cancelled'
  );
}

async function book(jar, classId) {
  log(`Creating reservation for class ${classId}…`);
  const { createReservation: result } = await gql(jar, `
    mutation ($id: ID!) {
      createReservation(classInstanceId: $id) {
        reservation {
          id status waitlistPosition createdAt
          classInstance { id classType startsAt coachName }
        }
        errorCode
      }
    }`, { id: classId });

  if (result.errorCode) {
    throw new Error(`Booking error: ${result.errorCode}`);
  }

  const r = result.reservation;
  if (r.status === 'confirmed') {
    log(`✅ CONFIRMED — reservation ${r.id}`);
    log(`   ${r.classInstance.classType} @ ${r.classInstance.startsAt} (coach ${r.classInstance.coachName})`);
  } else if (r.status === 'waitlisted') {
    log(`⏳ WAITLISTED — position ${r.waitlistPosition}, reservation ${r.id}`);
  } else {
    log(`Reservation ${r.id} — status: ${r.status}`);
  }
  return r;
}

// ── Main ────────────────────────────────────────────────────────────────

async function main() {
  const args = process.argv.slice(2);
  const dryRun = args.includes('--dry-run');
  const dateIdx = args.indexOf('--date');
  const dateArg = dateIdx >= 0 ? args[dateIdx + 1] : null;

  let targetDate;
  if (dateArg) {
    targetDate = new Date(dateArg + 'T00:00:00Z');
    if (isNaN(targetDate)) throw new Error(`Bad date: ${dateArg}`);
  } else {
    targetDate = nextWeekday(TARGET_DAY);
  }

  log(`🏋️  Target: ${fmtDate(targetDate)} — 7:00 PM AEST Open Gym`);

  const jar = new CookieJar();
  await login(jar);

  const cls = await findOpenGym(jar, targetDate);

  const existing = await alreadyBooked(jar, cls.id);
  if (existing) {
    log(`Already booked (${existing.status}), reservation ${existing.id}. Nothing to do.`);
    return;
  }

  if (cls.spotsLeft === 0) {
    log('⚠️  Class is full — will attempt anyway (may waitlist).');
  }

  if (dryRun) {
    log('🔍 Dry run — skipping booking.');
    return;
  }

  // Retry loop (fast retries for transient failures)
  const MAX = 3;
  for (let i = 1; i <= MAX; i++) {
    try {
      await book(jar, cls.id);
      return;
    } catch (err) {
      log(`Attempt ${i}/${MAX} failed: ${err.message}`);
      if (i < MAX) await new Promise(r => setTimeout(r, 1000 * i));
      else throw err;
    }
  }
}

main().catch(err => {
  log(`❌ FAILED: ${err.message}`);
  process.exit(1);
});

