async () => {
  // Query a wide range of Mondays — let's go 8 weeks out
  // First, find all classes across the next 8 weeks and filter to Monday Open Gym at 09:00 UTC
  const results = [];

  for (let week = 0; week < 8; week++) {
    const d = new Date('2026-08-17T00:00:00Z'); // This Monday
    d.setUTCDate(d.getUTCDate() + (week * 7));
    const from = d.toISOString().split('T')[0] + 'T00:00:00Z';
    const to = d.toISOString().split('T')[0] + 'T23:59:59Z';

    const r = await fetch('/graphql', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ 
      query: `query ($from: DateTime!, $to: DateTime!) {
        classes(from: $from, to: $to) { id classType startsAt capacity confirmedCount spotsLeft coachName }
      }`,
      variables: { from, to }
    })});
    const data = await r.json();

    const openGym = data.data?.classes?.find(c => 
      c.classType === 'open_gym' && new Date(c.startsAt).getUTCHours() === 9
    );

    if (openGym) {
      results.push({ date: d.toISOString().split('T')[0], ...openGym });
    } else {
      results.push({ date: d.toISOString().split('T')[0], error: 'not found', classes: data.data?.classes?.length || 0 });
    }
  }

  return results;
}

