async () => {
  // Try weeks 9-16 (Oct 12 through Nov 30)
  const results = [];

  for (let week = 8; week < 16; week++) {
    const d = new Date('2026-08-17T00:00:00Z');
    d.setUTCDate(d.getUTCDate() + (week * 7));
    const from = d.toISOString().split('T')[0] + 'T00:00:00Z';
    const to = d.toISOString().split('T')[0] + 'T23:59:59Z';

    const r = await fetch('/graphql', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ 
      query: `query ($from: DateTime!, $to: DateTime!) {
        classes(from: $from, to: $to) { id classType startsAt spotsLeft coachName }
      }`,
      variables: { from, to }
    })});
    const data = await r.json();

    const openGym = data.data?.classes?.find(c => 
      c.classType === 'open_gym' && new Date(c.startsAt).getUTCHours() === 9
    );

    results.push({ 
      date: d.toISOString().split('T')[0], 
      found: !!openGym,
      id: openGym?.id,
      spotsLeft: openGym?.spotsLeft,
      totalClasses: data.data?.classes?.length || 0
    });
  }

  return results;
}

